input.command:
wc -l $RUN_HOME/researchRalph/domains/nirenberg-1d-chan-free/results.tsv
echo "---"
echo "Best per branch:"
awk -F'\t' 'NR>1 && $5!="crash" {
  branch = "unknown"
  if ($4+0 > 0.5) branch = "positive"
  else if ($4+0 < -0.5) branch = "negative"
  else branch = "trivial"

  if (!(branch in best) || $2+0 < best[branch]+0) {
    best[branch] = $2
    exp[branch] = $1
    agent[branch] = $7
  }
}
END {
  for (b in best) printf "  %s: residual=%s (exp=%s, agent=%s)\n", b, best[b], exp[b], agent[b]
}' $RUN_HOME/researchRalph/domains/nirenberg-1d-chan-free/results.tsv

awk -F'\t' 'NR>1 && $5!="crash" {
